CREATE TABLE teacher_links (
    teacher_id INT PRIMARY KEY,
    mentor_id INT NULL,
    FOREIGN KEY (teacher_id) REFERENCES teachers(teacher_id),
    FOREIGN KEY (mentor_id) REFERENCES teachers(teacher_id)
) ENGINE=InnoDB;
INSERT INTO teacher_links VALUES (11, NULL), (12, 11), (13, 12), (14, 11);
WITH RECURSIVE team AS (
SELECT teacher_id FROM teacher_links WHERE teacher_id = 14
UNION ALL SELECT c.teacher_id FROM teacher_links AS c JOIN team AS p ON c.mentor_id = p.teacher_id
) SELECT COUNT(*) AS n FROM team;
